import{_ as r,C as s,o as i,c as n,a2 as t,E as d}from"./chunks/framework.DBKUV7en.js";const g=JSON.parse('{"title":"4. 「濃い」と「よく出ている」は別の話","description":"","frontmatter":{},"headers":[],"relativePath":"ch1/strength-vs-extraction.md","filePath":"ch1/strength-vs-extraction.md","lastUpdated":null}'),o={name:"ch1/strength-vs-extraction.md"};function l(p,a,h,c,b,f){const e=s("TasteCompass");return i(),n("div",null,[a[0]||(a[0]=t('<h1 id="_4-「濃い」と「よく出ている」は別の話" tabindex="-1">4. 「濃い」と「よく出ている」は別の話 <a class="header-anchor" href="#_4-「濃い」と「よく出ている」は別の話" aria-label="Permalink to &quot;4. 「濃い」と「よく出ている」は別の話&quot;">​</a></h1><p>僕も、ドリップをしていて、濃すぎたり薄すぎたり、味がうまく出ていない感じがすることがあります。</p><p>原因は、「濃い・薄い」と「出ている・出ていない」が、別の話だからです。濃度はカップの中身、抽出率は粉から取り出した量。お湯の量を変えると、動くのは主に<strong>濃度</strong>のほうです。この回は、抽出の話です。</p><h2 id="同じ粉でも、お湯が多ければ薄くなる" tabindex="-1">同じ粉でも、お湯が多ければ薄くなる <a class="header-anchor" href="#同じ粉でも、お湯が多ければ薄くなる" aria-label="Permalink to &quot;同じ粉でも、お湯が多ければ薄くなる&quot;">​</a></h2><p>濃度と抽出率は、こんな関係になります。</p><blockquote><p>濃度 ≒ 抽出率 × 粉の量 ÷ できた液の量</p></blockquote><p>粉15gで抽出率が20%なら、溶け出した成分は3gです。できた液が250gなら、濃度は3 ÷ 250で<strong>1.2%</strong>。液が300gなら1.0%です。粉の量も抽出率も同じなのに、お湯を増やしただけで濃度が下がりました。実際には、お湯を増やすと抽出率も少し上がるので、上は抽出率を同じとしたおおまかな計算です。</p><p>浸漬(水出しの仲間)では、抽出率が約21%で頭打ちになり、濃度は比率でほぼ決まります。透過式のドリップとの違いは、<a href="/coffee-textbook/basics/how-drip-works">第1回</a>に書いています。</p><p>薄いとか濃いだけなら、粉を増やせば直ります。「味が出ていない」とは別の問題です。</p><h2 id="濃度が高いと、酸っぱさも強まる" tabindex="-1">濃度が高いと、酸っぱさも強まる <a class="header-anchor" href="#濃度が高いと、酸っぱさも強まる" aria-label="Permalink to &quot;濃度が高いと、酸っぱさも強まる&quot;">​</a></h2><p>UC Davis のチームが2020年に行った研究では、濃度が上がると、苦さ、渋さ、口当たりの重さに加えて、酸っぱさも強くなりました(条件は<a href="/coffee-textbook/appendix/studies">付録</a>にまとめています)。</p><p>なので僕は、酸っぱいと感じたとき、細かく挽く前に、濃すぎないかを先に疑います。濃度を下げるだけで、酸っぱさが和らぐことがあるからです。</p><h2 id="_18〜22-は、迷ったときの出発点" tabindex="-1">18〜22%は、迷ったときの出発点 <a class="header-anchor" href="#_18〜22-は、迷ったときの出発点" aria-label="Permalink to &quot;18〜22%は、迷ったときの出発点&quot;">​</a></h2><p>抽出率18〜22%、濃度1.15〜1.35%(北米の目安。北欧は1.30〜1.50%くらい)が、ちょうどいい範囲として使われてきました。元は、1950年代のLockhartの研究の図です。</p><p>この目安は、近年の研究で見直されています。2021年の Cotter らの研究では、118人の消費者が27通りのコーヒーを飲んで、好みを答えました。好みは2つのグループに分かれ、その違いは主に濃度で出ています。</p><p>2023年の Guinard らは、これを含む3つの研究をまとめて、新しい抽出チャートを作りました。それによると、多数派の57%は、濃度が低めで抽出率18%付近を好みました。少数派の43%は、酸っぱくて果実感のある味と、ロースト感のある味の<strong>両方</strong>が好きでした。全体を平均すると古い目安に近い所に山が出ますが、2つのグループを混ぜた平均なので、誤解のもとだと著者は書いています。</p><p>参加者は主に北カリフォルニアの若い成人で、豆は1種類、ドリップのみです。著者自身も、別の地域では別のグループになりうると述べています。だから目安は、「ここに入れば正解」という線ではなく、出発点だと思っています。</p><h2 id="甘さは、薄めのほうが感じやすい" tabindex="-1">甘さは、薄めのほうが感じやすい? <a class="header-anchor" href="#甘さは、薄めのほうが感じやすい" aria-label="Permalink to &quot;甘さは、薄めのほうが感じやすい?&quot;">​</a></h2><p>コーヒーの甘さは、砂糖の味というより、かなりの部分を鼻で感じているようです。鼻をつまんで飲むと、甘さの評価が下がった、という試飲研究が紹介されています。何の成分が甘さをつくるのかは、まだ研究中です。</p><p>2024年の Liang らの研究(浸漬式)では、甘さだけが濃度と逆向きに動きました。ほかの味の項目は、濃度と同じ向きです。薄めに淹れると甘さを感じやすいことは、ありえそうです。ただ、豆は1種類で、焙煎は2段階。薄めて一晩冷蔵してから飲んだ研究なので、ドリップで同じかは分かっていません。</p><h2 id="味から、次の一手を決める" tabindex="-1">味から、次の一手を決める <a class="header-anchor" href="#味から、次の一手を決める" aria-label="Permalink to &quot;味から、次の一手を決める&quot;">​</a></h2><p>ドリップグリッドの縦軸(濃度)が、この回の主役です。</p>',22)),d(e,{highlight:"top"}),a[1]||(a[1]=t('<table tabindex="0"><thead><tr><th>感じた味</th><th>図のどこか</th><th>まず変えること(1つだけ)</th></tr></thead><tbody><tr><td>水っぽい・物足りない</td><td>下(薄い)</td><td>粉を少し増やす(またはお湯を減らす)</td></tr><tr><td>苦い・渋い・重い(酸っぱさも強い)</td><td>上(濃い)</td><td>お湯を少し増やす(または粉を減らす)</td></tr><tr><td>酸っぱい・青臭い(濃度は普通)</td><td>左(出きっていない)</td><td>挽き目を少し細かくする</td></tr></tbody></table><p>薄いだけのときは、味の方向は変わらず、ぼんやりします。出ていないときは、薄さに加えて、とがった酸っぱさや青臭さが目立ちます。これは僕の目安で、確かな線引きではありません。</p><h2 id="準備中" tabindex="-1">(準備中...) <a class="header-anchor" href="#準備中" aria-label="Permalink to &quot;(準備中...)&quot;">​</a></h2><p>比率だけを変えて3杯(1:14、1:16、1:18を考えています)淹れ比べる実験を予定しています。豆、挽き目、湯温はそろえます。「薄い」と「出ていない」の違いを舌で区別できるか、薄めのほうが甘く感じるかを見てみます。結果と動画は、できたらここに足します。</p><h2 id="確かさの一覧" tabindex="-1">確かさの一覧 <a class="header-anchor" href="#確かさの一覧" aria-label="Permalink to &quot;確かさの一覧&quot;">​</a></h2><details class="details custom-block"><summary>表を開く</summary><table tabindex="0"><thead><tr><th>書いたこと</th><th>確かさ</th></tr></thead><tbody><tr><td>濃度が上がると、苦さ・渋さ・重さに加えて酸っぱさも強まる</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> Batali ら 2020(UC Davis)。条件は付録</td></tr><tr><td>消費者の好みは2グループに分かれ、違いは主に濃度</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> Cotter ら 2021。要旨で確認</td></tr><tr><td>多数派57%は低めの濃度・抽出率18%付近、少数派43%は別の好み</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> Guinard ら 2023(本文で確認)。北カリフォルニアの若い成人に偏る。豆1種・ドリップのみ</td></tr><tr><td>18〜22%、1.15〜1.35%(北米)という目安</td><td><span class="stamp stamp-established ignore-header" tabindex="0" data-tip="信頼できる複数の情報源で、言っていることが一致している" aria-label="定説: 信頼できる複数の情報源で、言っていることが一致している">定説</span> 広く使われる目安。見直しが進んでいる</td></tr><tr><td>濃度 ≒ 抽出率 × 粉 ÷ 液量の計算</td><td><span class="stamp stamp-reasoning ignore-header" tabindex="0" data-tip="計算や、情報をつなげて考えたこと。研究そのものではない" aria-label="考察: 計算や、情報をつなげて考えたこと。研究そのものではない">考察</span> 考察</td></tr><tr><td>甘さのかなりの部分を鼻で感じている</td><td><span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span> 試飲研究の紹介記事。原文は未確認</td></tr><tr><td>甘さが濃度と逆向きに動く</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> Liang ら 2024(浸漬式・薄めて試飲)。ドリップで同じかは <span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span></td></tr><tr><td>「薄い」と「出ていない」の見分け方</td><td><span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span> 僕の目安。確かな線引きはない</td></tr></tbody></table></details><h2 id="出典" tabindex="-1">出典 <a class="header-anchor" href="#出典" aria-label="Permalink to &quot;出典&quot;">​</a></h2><ul><li>Batali, Ristenpart, Guinard (2020) Scientific Reports. <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC7536440/" target="_blank" rel="noreferrer">PMC</a></li><li>Cotter ら (2021) Journal of Food Science. <a href="https://ift.onlinelibrary.wiley.com/doi/10.1111/1750-3841.15561" target="_blank" rel="noreferrer">論文ページ</a></li><li>Guinard ら (2023) Journal of Food Science. <a href="https://ift.onlinelibrary.wiley.com/doi/10.1111/1750-3841.16531" target="_blank" rel="noreferrer">論文ページ</a></li><li>Fresh Cup (2024) <a href="https://freshcup.com/why-the-new-coffee-brewing-control-chart-is-a-big-deal/" target="_blank" rel="noreferrer">Why the New Coffee Brewing Control Chart Is a Big Deal</a>(2023年の研究の解説)</li><li>Liang ら (2024) Scientific Reports. <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC11335879/" target="_blank" rel="noreferrer">PMC</a></li><li>SCA / Coffee Science Foundation の甘さの研究(紹介記事). <a href="https://sca.coffee/sca-news/25/issue-22/understanding-coffee-sweetness-324dy" target="_blank" rel="noreferrer">SCA</a>、<a href="https://www.roastmagazine.com/stories/sweetness-in-coffee" target="_blank" rel="noreferrer">Roast Magazine</a></li></ul><p>次は、5. つまみと、ドリップグリッドの上での動き方<span class="soon">(準備中)</span>です。</p>',9))])}const u=r(o,[["render",l]]);export{g as __pageData,u as default};
